// Ground and shattered central avenue
box(scene,0,-.55,-43,180,1,160,M.ground);box(scene,0,-.035,-43,11,.05,110,M.road);
for(let i=0;i<30;i++){const x=(rand()-.5)*16,z=-rand()*102;const m=box(scene,x,.05,z,.25+rand()*.65,.05,.22+rand()*.7,i%3?M.concrete:M.brick,rand()*.3,rand()*3,rand()*.4);m.rotation.x+=rand()*.4;}
