 box(g,wx,wy,3.54,1.35,1.45,.08,M.window);box(g,wx,wy+.78,3.58,1.55,.12,.18,M.dark);if(r()>.48)box(g,wx-.7,wy,.12,.1,1.5,M.dark);if(r()>.62)box(g,wx,wy,.12,1.5,.1,M.dark);if(r()>.82)box(g,wx,wy+1,.2,1.4,.08,M.concrete,0,0,(r()-.5)*.4);}
