 for(let k=0;k<8;k++){const a=box(g,(r()-.5)*width,.3+ r()*.45,3.8+r()*2,.4+r()*1.1,.4,.4+r()*1.2,k%2?M.brick:M.concrete,r()*.5,r()*3,r()*.8);}
