const firelight=new THREE.PointLight(0xff7435,14,20);firelight.position.set(-9,2,-33);scene.add(firelight);const firemesh=new THREE.Mesh(new THREE.SphereGeometry(.45,8,7),M.fire);firemesh.position.set(-9,1,-33);scene.add(firemesh);
