for(const x of [-8,8]){cylinder(scene,x,3,-49,.1,.14,6,M.wood);box(scene,x,5.8,-49,1.1,.1,.1,M.dark,0,0,.08);}
function makeSoldier(type='ally',name=''){const g=new THREE.Group();const enemy=type==='enemy',civilian=type==='civilian';const coat=civilian?mat(0x756451):enemy?M.enemy:M.uniform;const pants=civilian?mat(0x49443b):enemy?mat(0x45453f):mat(0x44483e);const skin=M.skin;
 const torso=cylinder(g,0,1.27,0,.38,.31,.9,coat,9);torso.rotation.z=Math.PI/2; // torso replaced by broad tunic box for readable silhouette
 box(g,0,1.34,0,.68,.85,.39,coat,0,0,.02);cylinder(g,0,1.85,0,.22,.24,.22,skin,9);
 if(!civilian){const hat=cylinder(g,0,2.01,0,.29,.26,.2,enemy?mat(0x45443e):mat(0x515747),9);box(g,0,1.97,.23,.42,.06,.24,enemy?mat(0x45443e):mat(0x515747));}
 else{const hair=new THREE.Mesh(new THREE.SphereGeometry(.25,8,7),mat(0x403b34));hair.position.set(0,1.9,-.03);g.add(hair);}
 for(const side of [-1,1]){cylinder(g,side*.19,.55,0,.13,.16,.95,pants,7).position.x=side*.19;const arm=cylinder(g,side*.44,1.34,0,.12,.15,.63,coat,7);arm.rotation.z=side*.14;box(g,side*.19,.11,0,.25,.58,.3,pants);}
 if(enemy||type==='ally'){const gun=box(g,.43,1.18,.27,.12,.11,.82,M.dark,0,0,-.08);gun.rotation.x=.06;}
 g.userData={type,name,health:enemy?2:100,alive:true,phase:Math.random()*6};return g;}
const player=makeSoldier('player','Nikolai');scene.add(player);player.position.set(0,0,5);player.rotation.y=0;
const orlov=makeSoldier('ally','Sergeant Orlov');scene.add(orlov);orlov.position.set(-2,0,-15);orlov.rotation.y=.35;
const ally2=makeSoldier('ally','Mikhail');scene.add(ally2);ally2.position.set(-4.2,0,-17);ally2.rotation.y=-.2;
const family=[makeSoldier('civilian','Anna'),makeSoldier('civilian','Pavel')];family.forEach((g,i)=>{scene.add(g);g.position.set(1.7+i*.65,0,-39-i*.5);g.scale.setScalar(i?.76:.9);g.rotation.y=Math.PI;});
const enemies=[];[[-3,-51],[3,-56],[-1,-63]].forEach((p,i)=>{const e=makeSoldier('enemy','Rifleman');scene.add(e);e.position.set(p[0],0,p[1]);e.rotation.y=Math.PI;enemies.push(e);});
// Directional objective marker, dust motes and distant smoke plumes
const markerMat=new THREE.MeshBasicMaterial({color:0xe4bc70,transparent:true,opacity:.8});const marker=new THREE.Mesh(new THREE.TorusGeometry(.8,.055,7,24),markerMat);marker.rotation.x=-Math.PI/2;scene.add(marker);
const beacon=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,2.4,6),new THREE.MeshBasicMaterial({color:0xe4bc70,transparent:true,opacity:.35}));scene.add(beacon);
const smoke=[];for(let i=0;i<8;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.7+rand()*.65,7,6),new THREE.MeshBasicMaterial({color:0x57564e,transparent:true,opacity:.17}));m.position.set(-9+rand()*2,3+rand()*3,-33-rand()*3);scene.add(m);smoke.push(m);}
let yaw=0,pitch=-.06,health=100,ammo=5,reserve=30,stage=0,dead=false,playing=false,lastShot=0,enemyTick=0,toastTimer=0,locked=false,moveX=0,moveY=0,aimHeld=false,audioCtx=null;
const keys={};const raycaster=new THREE.Raycaster();raycaster.far=70;
const $=s=>document.querySelector(s);const HUD=$('#hud'),menu=$('#menu'),brief=$('#briefing');
function showToast(text){const el=$('#toast');el.innerHTML=text;el.classList.add('show');toastTimer=2.8;}
function setStage(n){stage=n;const labels=['Rendezvous with Sergeant Orlov near the shattered tram.','Help the family reach the cellar passage.','Silence the enemy fire at the crossing.','Reach the Volga-side evacuation point.'];$('#objectiveText').textContent=labels[Math.min(stage,3)];$('#objectiveCount').textContent=stage<3?`OBJECTIVE 0${stage+1} / 03`:'OBJECTIVE 03 / 03';if(stage===1)showToast('ORLOV: “The cellar passage. Take them east, keep low.”');if(stage===2){showToast('The family is moving. Enemy fire ahead — hold the crossing.');enemies.forEach(e=>e.userData.alert=true);}if(stage===3)showToast('The street is clear. Move to the evacuation marker.');if(stage===4){$('#briefTitle').textContent='The river is still there';$('#briefText').textContent='Anna and Pavel reach the shelter. Orlov stays behind with the wounded as the squad withdraws toward the Volga. The city is not free yet, but tonight, two more people will see morning.';brief.style.display='flex';playing=false;document.exitPointerLock?.();$('#briefContinue').textContent='Return to the front';$('#briefContinue').onclick=()=>location.reload();}}
function beginGame(){menu.classList.add('hidden');setTimeout(()=>menu.style.display='none',600);HUD.style.display='block';playing=true;brief.style.display='none';showToast('STALINGRAD · 13 SEPTEMBER 1942');if(innerWidth>700)renderer.domElement.requestPointerLock?.();}
$('#start').addEventListener('click',()=>{brief.style.display='flex';});$('#briefContinue').addEventListener('click',()=>{beginGame();});$('#controls').addEventListener('click',()=>{alert('WASD: move · Mouse: look · Left click: fire · R: reload · E: interact · Shift: run. On touchscreens, use the left pad to move and the buttons to fire, interact, and reload. Gamepads are supported.');});
document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===renderer.domElement;});document.addEventListener('mousemove',e=>{if(locked&&playing){yaw-=e.movementX*.0021;pitch=Math.max(-.55,Math.min(.38,pitch-e.movementY*.0017));}});
function wakeAudio(){if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();}
function sound(freq=100,duration=.09,volume=.07){try{wakeAudio();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sawtooth';o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(28,freq*.35),audioCtx.currentTime+duration);g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}
function fire(){if(!playing||dead||performance.now()-lastShot<360)return;lastShot=performance.now();if(ammo<=0){showToast('Magazine empty — press R to reload');return;}ammo--;$('#ammoNum').textContent=String(ammo).padStart(2,'0');sound(135,.12,.075);camera.updateMatrixWorld();raycaster.setFromCamera(new THREE.Vector2(0,0),camera);const candidates=enemies.filter(e=>e.userData.alive).flatMap(e=>e.children);const hit=raycaster.intersectObjects(candidates,true)[0];if(hit){const e=enemies.find(e=>e===hit.object||e.getObjectById(hit.object.id));if(e&&e.userData.alive){e.userData.health--;e.userData.hitFlash=.14;$('#hitmarker').style.display='block';setTimeout(()=>$('#hitmarker').style.display='none',100);if(e.userData.health<=0){e.userData.alive=false;e.rotation.z=.95;e.position.y=-.1;e.traverse(o=>{if(o.isMesh)o.material=mat(0x343632);});showToast('Threat neutralized');if(enemies.every(x=>!x.userData.alive)&&stage===2)setStage(3);}return;}}
 // missed-round spark at the far end of the sightline
 const p=camera.position.clone().add(raycaster.ray.direction.clone().multiplyScalar(23));const spark=new THREE.Mesh(new THREE.SphereGeometry(.06,5,4),new THREE.MeshBasicMaterial({color:0xffd385}));spark.position.copy(p);scene.add(spark);setTimeout(()=>scene.remove(spark),90);}
function reload(){if(!playing||reserve<=0||ammo>=5)return;const n=Math.min(5-ammo,reserve);ammo+=n;reserve-=n;$('#ammoNum').textContent=String(ammo).padStart(2,'0');sound(420,.055,.025);showToast('Reloading — keep your head down');}
function interact(){if(!playing||stage!==1)return;const d=player.position.distanceTo(new THREE.Vector3(2,0,-39));if(d<4.2){family.forEach((g,i)=>{g.userData.follow=true;g.rotation.y=0;});setStage(2);}}
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.code==='KeyE')interact();if(e.code==='KeyR')reload();});addEventListener('keyup',e=>keys[e.code]=false);renderer.domElement.addEventListener('mousedown',e=>{if(e.button===0){wakeAudio();fire();}});renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());
$('#touchFire').addEventListener('pointerdown',e=>{e.preventDefault();fire();});$('#touchUse').addEventListener('pointerdown',e=>{e.preventDefault();interact();});$('#touchReload').addEventListener('pointerdown',e=>{e.preventDefault();reload();});$('#touchAim').addEventListener('pointerdown',()=>{aimHeld=!aimHeld;camera.fov=aimHeld?46:62;camera.updateProjectionMatrix();});

