<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9b9889);scene.fog=new THREE.FogExp2(0x9b9889,.012);
const camera=new THREE.PerspectiveCamera(62,innerWidth/innerHeight,.1,220);camera.position.set(0,7,25);camera.lookAt(0,3,-28);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc8d1d2,0x423d31,2.0));const sun=new THREE.DirectionalLight(0xffdfb1,2.5);sun.position.set(-25,38,10);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
const mat=(color,rough=.9)=>new THREE.MeshStandardMaterial({color,roughness:rough});
const M={ground:mat(0x514b40),road:mat(0x48463f),concrete:mat(0x766f61),brick:mat(0x64564a),dark:mat(0x292c29),window:mat(0x181d1e),wood:mat(0x574b3a),sandbag:mat(0x82765d),metal:mat(0x4d504a),uniform:mat(0x555d4e),skin:mat(0xb78f70),enemy:mat(0x55534b),gold:mat(0xd0ae6a),fire: new THREE.MeshBasicMaterial({color:0xff9a41})};
function box(parent,x,y,z,w,h,d,material,rx=0,ry=0,rz=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.rotation.set(rx,ry,rz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,material,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}
function seedRand(seed){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}}const rand=seedRand(42);
// Ground and shattered central avenue
box(scene,0,-.55,-43,180,1,160,M.ground);box(scene,0,-.035,-43,11,.05,110,M.road);
for(let i=0;i<30;i++){const x=(rand()-.5)*16,z=-rand()*102;const m=box(scene,x,.05,z,.25+rand()*.65,.05,.22+rand()*.7,i%3?M.concrete:M.brick,rand()*.3,rand()*3,rand()*.4);m.rotation.x+=rand()*.4;}
// War-torn apartment shells with fractured roofs, dark windows and exposed brick
function building(side,z,width,height,seed){const r=seedRand(seed);const x=side*12.7;const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);const base=side<0?M.brick:M.concrete;
 box(g,0,height/2,0,width,height,7,base);box(g,0,height+.05,0,width+.4,.25,7.5,M.dark,0,0,(r()-.5)*.045);
 for(let floor=0;floor<Math.floor(height/3);floor++)for(let col=0;col<Math.floor(width/2.5);col++){if(r()<.18)continue;const wx=-width/2+1.35+col*2.5,wy=1.2+floor*3;
 box(g,wx,wy,3.54,1.35,1.45,.08,M.window);box(g,wx,wy+.78,3.58,1.55,.12,.18,M.dark);if(r()>.48)box(g,wx-.7,wy,3.62,.1,1.5,.12,M.dark);if(r()>.62)box(g,wx,wy,3.62,1.5,.1,.12,M.dark);if(r()>.82)box(g,wx,wy+1,3.62,1.4,.08,.12,M.concrete,0,0,(r()-.5)*.4);}
 // Torn-off upper corner, debris and a hanging beam
 if(r()>.3){const bite=box(g,side*width*.32,height-.2,3.1,width*.34,1.8,.7,M.brick,0,0,(r()-.5)*.28);bite.position.y=height-.4;box(g,-side*width*.22,height*.64,3.8,.16,2.7,.18,M.wood,0,0,.4);}
 for(let k=0;k<8;k++){const a=box(g,(r()-.5)*width,.3+ r()*.45,3.8+r()*2,.4+r()*1.1,.4,.4+r()*1.2,k%2?M.brick:M.concrete,r()*.5,r()*3,r()*.8);}
 // A broken roofline
 for(let k=0;k<3;k++)box(g,(r()-.5)*width,height+.35+r()*.6,(r()-.5)*5,.25,1+r(),.3,M.brick,0,0,(r()-.5)*.8);
}
[[-1,-13,15,12,8],[1,-10,14,15,14],[-1,-34,17,14,27],[1,-32,14,11,30],[-1,-58,15,16,41],[1,-57,16,13,48],[-1,-82,16,12,53],[1,-83,18,16,62]].forEach(a=>building(...a));
// broken tram, shell craters, sandbag position and props
const tram=new THREE.Group();scene.add(tram);tram.position.set(-3,.1,-17);tram.rotation.y=-.12;
box(tram,0,1.3,0,4.2,1.9,8,M.metal);box(tram,0,2.3,-.4,3.9,.25,7.4,M.dark);for(let z=-3;z<=3;z+=2)box(tram,0,1.85,z,3.9,.12,.08,M.window);for(let x of [-1.4,1.4])for(let z of [-2.7,2.7])cylinder(tram,x,.3,z,.43,.43,.22,M.dark,12);box(tram,1,2.7,1.7,1.2,.35,1.5,M.wood,0,0,.2);
for(let i=0;i<8;i++){const s=box(scene,5+(i%4)*.68,.37,-40-Math.floor(i/4)*.45,.8,.72,.48,M.sandbag,0,0,(rand()-.5)*.08);}
// Crater rims and firelight
for(const [x,z,r] of [[-6,-24,2.3],[5,-49,2.1],[-4,-72,2.7]]){const crater=new THREE.Mesh(new THREE.TorusGeometry(r,.28,5,14),M.road);crater.rotation.x=-Math.PI/2;crater.position.set(x,.04,z);crater.receiveShadow=true;scene.add(crater);}
const firelight=new THREE.PointLight(0xff7435,14,20);firelight.position.set(-9,2,-33);scene.add(firelight);const firemesh=new THREE.Mesh(new THREE.SphereGeometry(.45,8,7),M.fire);firemesh.position.set(-9,1,-33);scene.add(firemesh);
// Rubble street dressing and utility poles
for(const x of [-8,8]){cylinder(scene,x,3,-49,.1,.14,6,M.wood);box(scene,x,5.8,-49,1.1,.1,.1,M.dark,0,0,.08);}
function makeSoldier(type='ally',name=''){const g=new THREE.Group();const enemy=type==='enemy',civilian=type==='civilian';const coat=civilian?mat(0x756451):enemy?M.enemy:M.uniform;const pants=civilian?mat(0x49443b):enemy?mat(0x45453f):mat(0x44483e);const skin=M.skin;
 box(g,0,1.34,0,.68,.85,.39,coat,0,0,.02);cylinder(g,0,1.85,0,.22,.24,.22,skin,9);
 if(!civilian){const hat=cylinder(g,0,2.01,0,.29,.26,.2,enemy?mat(0x45443e):mat(0x515747),9);box(g,0,1.97,.23,.42,.06,.24,enemy?mat(0x45443e):mat(0x515747));}
 else{const hair=new THREE.Mesh(new THREE.SphereGeometry(.25,8,7),mat(0x403b34));hair.position.set(0,1.9,-.03);g.add(hair);}
 for(const side of [-1,1]){cylinder(g,side*.19,.55,0,.13,.16,.95,pants,7).position.x=side*.19;const arm=cylinder(g,side*.44,1.34,0,.12,.15,.63,coat,7);arm.rotation.z=side*.14;box(g,side*.19,.11,0,.25,.58,.3,pants);}
 if(enemy||type==='ally'){const gun=box(g,.43,1.18,.27,.12,.11,.82,M.dark,0,0,-.08);gun.rotation.x=.06;}
 g.userData={type,name,health:enemy?2:100,alive:true,phase:Math.random()*6};return g;}
const player=makeSoldier('player','Nikolai');scene.add(player);player.position.set(0,0,5);player.rotation.y=0;
const orlov=makeSoldier('ally','Sergeant Orlov');scene.add(orlov);orlov.position.set(-2,0,-15);orlov.rotation.y=.35;
const ally2=makeSoldier('ally','Mikhail');scene.add(ally2);ally2.position.set(-4.2,0,-17);ally2.rotation.y=-.2;
const family=[makeSoldier('civilian','Anna'),makeSoldier('civilian','Pavel')];family.forEach((g,i)=>{scene.add(g);g.position.set(1.7+i*.65,0,-39-i*.5);g.scale.setScalar(i?.76:.9);g.rotation.y=Math.PI;});
const enemies=[];[[-3,-51],[3,-56],[-1,-63]].forEach((p,i)=>{const e=makeSoldier('enemy','Rifleman');scene.add(e);e.position.set(p[0],0,p[1]);e.rotation.y=Math.PI;enemies.push(e);});
// Directional objective marker, dust motes and distant smoke plumes
const markerMat=new THREE.MeshBasicMaterial({color:0xe4bc70,transparent:true,opacity:.8});const marker=new THREE.Mesh(new THREE.TorusGeometry(.8,.055,7,24),markerMat);marker.rotation.x=-Math.PI/2;scene.add(marker);
const beacon=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,2.4,6),new THREE.MeshBasicMaterial({color:0xe4bc70,transparent:true,opacity:.35}));scene.add(beacon);
const smoke=[];for(let i=0;i<8;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.7+rand()*.65,7,6),new THREE.MeshBasicMaterial({color:0x57564e,transparent:true,opacity:.17}));m.position.set(-9+rand()*2,3+rand()*3,-33-rand()*3);scene.add(m);smoke.push(m);}
let yaw=0,pitch=-.06,health=100,ammo=5,reserve=30,stage=0,dead=false,playing=false,lastShot=0,enemyTick=0,toastTimer=0,locked=false,moveX=0,moveY=0,aimHeld=false,audioCtx=null;
const keys={};const raycaster=new THREE.Raycaster();raycaster.far=70;
const $=s=>document.querySelector(s);const HUD=$('#hud'),menu=$('#menu'),brief=$('#briefing'),options=$('#options');
const quality=$('#quality');quality.value=localStorage.getItem('frontlines-quality')||'balanced';
function applyQuality(){const q=quality.value;renderer.setPixelRatio(Math.min(devicePixelRatio,q==='low'?1:q==='balanced'?1.5:2));renderer.shadowMap.enabled=q!=='low';renderer.setSize(innerWidth,innerHeight);localStorage.setItem('frontlines-quality',q);}
applyQuality();
$('#controls').addEventListener('click',()=>{options.style.display='flex';});$('#closeSettings').addEventListener('click',()=>{options.style.display='none';});$('#applySettings').addEventListener('click',()=>{applyQuality();options.style.display='none';});
